    BEGIN
      res := pg_temp.c_c9f_log_fails();
      RAISE EXCEPTION 'undo-case';
    EXCEPTION WHEN OTHERS THEN
      IF SQLERRM <> 'undo-case' THEN res := 'ERROR ' || SQLSTATE || ' ' || left(SQLERRM, 400); END IF;
    END;
    base := base || jsonb_build_object('c_c9f_log_fails', res);
    BEGIN
      res := pg_temp.c_c9g_no_read_no_row();
      RAISE EXCEPTION 'undo-case';
    EXCEPTION WHEN OTHERS THEN
      IF SQLERRM <> 'undo-case' THEN res := 'ERROR ' || SQLSTATE || ' ' || left(SQLERRM, 400); END IF;
    END;
    base := base || jsonb_build_object('c_c9g_no_read_no_row', res);
    BEGIN
      res := pg_temp.c_c9h_inactive();
